function ensureVaultStyles() {
  if (typeof document === "undefined") return;
  const existing = document.getElementById(STYLE_ID20);
  if (existing !== null) {
    if (existing.textContent !== SHEET20) existing.textContent = SHEET20;
    return;
  }
  const tag = document.createElement("style");
  tag.id = STYLE_ID20;
  tag.dataset.plugin = "dsh-chat-plus";
  tag.textContent = SHEET20;
  document.head.appendChild(tag);
}

