function ensureSystemPromptStyles() {
  if (typeof document === "undefined") return;
  const existing = document.getElementById(STYLE_ID21);
  if (existing !== null) {
    if (existing.textContent !== SHEET21) existing.textContent = SHEET21;
    return;
  }
  const tag = document.createElement("style");
  tag.id = STYLE_ID21;
  tag.dataset.plugin = "dsh-chat-plus";
  tag.textContent = SHEET21;
  document.head.appendChild(tag);
}

